"""
Per-task subgraph factory for the Milestone 5 Code Generation workflow.

build_task_subgraph(task, max_retries)
    Compiles (or retrieves from cache) a LangGraph StateGraph[TaskState]
    whose topology is driven by task.pattern_refs.

    With "Reflection" pattern
    -------------------------
    START
      └─► developer_node
               └─► critic_node
                     └─► [_route_after_critic]
                               ├─(to_developer)─► developer_node        ← critic loop
                               └─(to_reviewers)─► dispatch_to_reviewers
                                                        ├─► workflow_reviewer_node ─┐
                                                        ├─► prompt_reviewer_node   ─┤
                                                        └─► security_reviewer_node ─┘
                                                                └─► reduce_verdicts_node
                                                                          └─► [route_after_reduce]
                                                                                    ├─(retry)───► developer_node
                                                                                    ├─(finalize)► finalize_task_node → END
                                                                                    └─(fail)────► finalize_task_node → END

    Without "Reflection" pattern
    ----------------------------
    START
      └─► developer_node
               └─► dispatch_to_reviewers
                        ├─► workflow_reviewer_node ─┐
                        ├─► prompt_reviewer_node   ─┤
                        └─► security_reviewer_node ─┘
                                └─► reduce_verdicts_node
                                          └─► [route_after_reduce]
                                                    ├─(retry)───► developer_node
                                                    ├─(finalize)► finalize_task_node → END
                                                    └─(fail)────► finalize_task_node → END

log_topology(task)
    Logs the topology description for the task before subgraph invocation.
    Called from graph.py's execute_task_node — pure side-effect, no return value.

Caching
-------
Compiled graphs are cached by (frozenset(pattern_refs), max_retries).
Recompilation is expensive; most runs share the same pattern combination
across all their tasks so the cache typically hits after the first task.
"""

from __future__ import annotations

import logging
from typing import Optional

from langgraph.graph import END, START, StateGraph
from app.hooks.node_hooks import node_hook

from app.workflows.codegen.nodes import (
    critic_node,
    developer_node,
    finalize_task_node,
    prompt_reviewer_node,
    reduce_verdicts_node,
    route_after_reduce,
    security_reviewer_node,
    tool_syntax_check_node,
    workflow_reviewer_node,
)
from app.workflows.codegen.prompts import REFLECTION_PATTERNS, TOOL_USE_PATTERNS
from app.workflows.codegen.state import TaskRecord, TaskRoute, TaskState

log = logging.getLogger(__name__)


def _has_any_pattern(pattern_refs: list[str], candidates: set[str]) -> bool:
    """Return True when any planner-emitted pattern matches a canonical set."""
    return any(pattern in candidates for pattern in pattern_refs)


# ---------------------------------------------------------------------------
# Subgraph cache
# ---------------------------------------------------------------------------

_SUBGRAPH_CACHE: dict[tuple, object] = {}


def clear_subgraph_cache() -> None:
    """Clear compiled per-task subgraphs."""
    _SUBGRAPH_CACHE.clear()


def get_cached_patterns() -> list[list[str]]:
    """Return cached pattern combinations for diagnostics and tests."""
    return [sorted(patterns) for patterns in _SUBGRAPH_CACHE.keys()]


def _cache_key(task: TaskRecord, max_retries: int) -> frozenset[str]:
    """Stable cache key based on canonical topology labels, not raw aliases."""
    supported: list[str] = []
    if _has_any_pattern(task.pattern_refs, REFLECTION_PATTERNS):
        supported.append("Reflection")
    if _has_any_pattern(task.pattern_refs, TOOL_USE_PATTERNS):
        supported.append("Tool-Use")
    return frozenset(supported)

# ---------------------------------------------------------------------------
# Passthrough fan-out hub
# ---------------------------------------------------------------------------

async def _dispatch_to_reviewers(state: TaskState) -> TaskState:
    """
    No-op passthrough node used as the reviewer fan-out hub.

    LangGraph conditional edges map one return value to exactly one target.
    Without this hub we cannot fan out from critic_node (or developer_node)
    to three parallel reviewer nodes in a single step.  This node adds zero
    logic — its only job is to hold three outgoing add_edge calls.
    """
    return state


# ---------------------------------------------------------------------------
# Critic routing (corrected local version)
# ---------------------------------------------------------------------------
# route_after_critic in nodes.py returns TO_REVIEWERS on both branches —
# intentionally left for subgraph.py to wire.  We define a clean router here.

_ROUTE_TO_DEVELOPER = "to_developer"
_ROUTE_TO_PROCEED_REVIEW = TaskRoute.TO_REVIEWERS   # "to_reviewers"
_ROUTE_TO_FAN_OUT = "to_fan_out"
_ROUTE_TO_TOOL_CHECK = "to_tool_check"
_ROUTE_TO_CRITIC = "to_critic"
_ROUTE_TO_FINALIZE = "to_finalize"

_TO_DEVELOPER = _ROUTE_TO_DEVELOPER
_TO_REVIEWERS = _ROUTE_TO_PROCEED_REVIEW


def _route_after_developer(has_tool_use: bool, has_reflection: bool):
    """Build a developer router for the current topology."""
    def _route(state: TaskState) -> str:
        if state.get("error") or not state.get("pending_files"):
            return _ROUTE_TO_FINALIZE
        if has_tool_use:
            return _ROUTE_TO_TOOL_CHECK
        if has_reflection:
            return _ROUTE_TO_CRITIC
        return _ROUTE_TO_FAN_OUT
    return _route


def _route_after_reduce_with_cap(state: TaskState) -> str:
    """Compatibility wrapper for route_after_reduce."""
    return route_after_reduce(state)


def _route_after_tool_check(state: TaskState) -> str:
    """Route after a Tool-Use syntax check."""
    if not state.get("aggregated_feedback"):
        return _ROUTE_TO_FAN_OUT
    if state.get("retry_count", 0) > state.get("max_retries", 3):
        return TaskRoute.FAIL
    return _ROUTE_TO_DEVELOPER

def _route_after_critic(state: TaskState) -> str:
    """
    critic_feedback is set  -> critic rejected output -> back to developer_node
    critic_feedback is None -> critic passed          -> proceed to reviewer fan-out
    """
    if state.get("critic_feedback"):
        if state.get("retry_count", 0) > state.get("max_retries", 3):
            return TaskRoute.FAIL
        return _TO_DEVELOPER
    return _TO_REVIEWERS


# ---------------------------------------------------------------------------
# log_topology
# ---------------------------------------------------------------------------

def log_topology(task: TaskRecord) -> None:
    """Log the subgraph topology that will be compiled for this task."""
    has_reflection = _has_any_pattern(task.pattern_refs, REFLECTION_PATTERNS)
    has_tool_use = _has_any_pattern(task.pattern_refs, TOOL_USE_PATTERNS)

    steps = ["START", "developer"]
    if has_tool_use:
        steps.append("tool_check")
    if has_reflection:
        steps.append("critic")
    steps.extend(["reviewers", "reduce", "finalize", "END"])

    log.info(
        "log_topology | task_id=%s | patterns=%s | topology: %s",
        task.id,
        task.pattern_refs,
        " -> ".join(steps),
    )


# ---------------------------------------------------------------------------
# build_task_subgraph
# ---------------------------------------------------------------------------

def build_task_subgraph(task: TaskRecord, max_retries: int = 3):
    """
    Build (or retrieve from cache) a compiled subgraph for the given task.

    The graph shape is selected from the task's pattern_refs. Reflection adds
    a critic loop, Tool-Use adds a static tool syntax gate, and every topology
    ends with parallel reviewer subagents plus a retry reducer.
    """
    key = _cache_key(task, max_retries)

    if key in _SUBGRAPH_CACHE:
        log.debug(
            "build_task_subgraph | cache HIT  | patterns=%s | max_retries=%d",
            task.pattern_refs, max_retries,
        )
        return _SUBGRAPH_CACHE[key]

    log.info(
        "build_task_subgraph | cache MISS | patterns=%s | max_retries=%d",
        task.pattern_refs, max_retries,
    )

    has_reflection = _has_any_pattern(task.pattern_refs, REFLECTION_PATTERNS)
    has_tool_use = _has_any_pattern(task.pattern_refs, TOOL_USE_PATTERNS)

    graph = StateGraph(TaskState)

    graph.add_node("developer_node",          node_hook("developer_node")(developer_node))
    graph.add_node("dispatch_to_reviewers",   node_hook("dispatch_to_reviewers")(_dispatch_to_reviewers))
    graph.add_node("workflow_reviewer_node",  node_hook("workflow_reviewer_node")(workflow_reviewer_node))
    graph.add_node("prompt_reviewer_node",    node_hook("prompt_reviewer_node")(prompt_reviewer_node))
    graph.add_node("security_reviewer_node",  node_hook("security_reviewer_node")(security_reviewer_node))
    graph.add_node("reduce_verdicts_node",    node_hook("reduce_verdicts_node")(reduce_verdicts_node))
    graph.add_node("finalize_task_node",      node_hook("finalize_task_node")(finalize_task_node))

    if has_tool_use:
        graph.add_node("tool_syntax_check_node", node_hook("tool_syntax_check_node")(tool_syntax_check_node))
    if has_reflection:
        graph.add_node("critic_node", node_hook("critic_node")(critic_node))

    graph.add_edge(START, "developer_node")

    developer_targets = {
        _ROUTE_TO_FINALIZE: "finalize_task_node",
        _ROUTE_TO_FAN_OUT: "dispatch_to_reviewers",
    }
    if has_tool_use:
        developer_targets[_ROUTE_TO_TOOL_CHECK] = "tool_syntax_check_node"
    if has_reflection:
        developer_targets[_ROUTE_TO_CRITIC] = "critic_node"

    graph.add_conditional_edges(
        "developer_node",
        _route_after_developer(has_tool_use, has_reflection),
        developer_targets,
    )

    if has_tool_use:
        graph.add_conditional_edges(
            "tool_syntax_check_node",
            _route_after_tool_check,
            {
                _ROUTE_TO_FAN_OUT: "critic_node" if has_reflection else "dispatch_to_reviewers",
                _ROUTE_TO_DEVELOPER: "developer_node",
                TaskRoute.FAIL: "finalize_task_node",
            },
        )

    if has_reflection:
        graph.add_conditional_edges(
            "critic_node",
            _route_after_critic,
            {
                _TO_DEVELOPER: "developer_node",
                _TO_REVIEWERS: "dispatch_to_reviewers",
                TaskRoute.FAIL: "finalize_task_node",
            },
        )

    graph.add_edge("dispatch_to_reviewers", "workflow_reviewer_node")
    graph.add_edge("dispatch_to_reviewers", "prompt_reviewer_node")
    graph.add_edge("dispatch_to_reviewers", "security_reviewer_node")

    graph.add_edge("workflow_reviewer_node", "reduce_verdicts_node")
    graph.add_edge("prompt_reviewer_node",   "reduce_verdicts_node")
    graph.add_edge("security_reviewer_node", "reduce_verdicts_node")

    graph.add_conditional_edges(
        "reduce_verdicts_node",
        route_after_reduce,
        {
            TaskRoute.RETRY:    "developer_node",
            TaskRoute.FINALIZE: "finalize_task_node",
            TaskRoute.FAIL:     "finalize_task_node",
        },
    )

    graph.add_edge("finalize_task_node", END)

    compiled = graph.compile()
    _SUBGRAPH_CACHE[key] = compiled

    log.info(
        "build_task_subgraph | compiled and cached | patterns=%s | max_retries=%d",
        task.pattern_refs, max_retries,
    )
    return compiled
